259			}
260			if !addressOK || !typeOK || !hasProps || !propsOK {
261				continue
262			}
263			resources[i] = planResource{address: address, typ: typ, properties: props}
264		}
265		if len(errs) != 0 {
266			return nil, nil, errs
267		}
268	
269		addresses := make([]string, len(entries))
270		for i, resource := range resources {
271			addresses[i] = resource.address
272		}
273		dependsOn, order, depErrs := resolveDependencies(entries, addresses, base+"/resources")
274		if len(depErrs) != 0 {
275			return nil, nil, depErrs
276		}
277		for i := range resources {
278			resources[i].dependsOn = dependsOn[i]
279		}
280		return resources, order, nil
281	}
