283	// planStringField extracts a required non-empty string field of a prior
284	// state entry, reporting invalid_plan_request otherwise.
285	func planStringField(obj map[string]any, field, path string, add func(code, message, path string)) (string, bool) {
286		raw, ok := obj[field]
287		if !ok {
288			add(codeInvalidPlanRequest, fmt.Sprintf("missing required field %q", field), path)
289			return "", false
290		}
291		s, ok := raw.(string)
292		if !ok {
293			add(codeInvalidPlanRequest, fmt.Sprintf("%q must be a string", field), path+"/"+field)
294			return "", false
295		}
296		if s == "" {
297			add(codeInvalidPlanRequest, fmt.Sprintf("%q must not be empty", field), path+"/"+field)
298			return "", false
299		}
300		return s, true
301	}
302	
303	// computePlan aligns desired and prior resources by address. Deletes are
304	// listed in the reverse of the prior state's topological order; creates and
305	// updates follow the configuration's deterministic topological order.
306	// Resources equal on both sides are counted as noop and produce no change.
307	func computePlan(configResources []planResource, configOrder []string, stateResources []planResource, stateOrder []string) ([]planChange, planSummary) {
308		configByAddress := make(map[string]planResource, len(configResources))
309		for _, resource := range configResources {
310			configByAddress[resource.address] = resource
311		}
312		stateByAddress := make(map[string]planResource, len(stateResources))
313		for _, resource := range stateResources {
314			stateByAddress[resource.address] = resource
315		}
316	
317		actions := make(map[string]string, len(configResources)+len(stateResources))
318		var summary planSummary
319		for _, resource := range configResources {
320			prior, existed := stateByAddress[resource.address]
321			switch {
322			case !existed:
323				actions[resource.address] = "create"
324				summary.Create++
325			case resourceEqual(resource, prior):
326				summary.Noop++
327			default:
328				actions[resource.address] = "update"
329				summary.Update++
330			}
331		}
332		for _, resource := range stateResources {
333			if _, desired := configByAddress[resource.address]; !desired {
334				actions[resource.address] = "delete"
335				summary.Delete++
336			}
337		}
338	
339		changes := make([]planChange, 0, len(actions))
340		for i := len(stateOrder) - 1; i >= 0; i-- {
341			address := stateOrder[i]
342			if actions[address] != "delete" {
343				continue
344			}
345			before := snapshotOf(stateByAddress[address])
346			changes = append(changes, planChange{Address: address, Action: "delete", Before: &before})
347		}
348		for _, address := range configOrder {
349			action := actions[address]
350			if action != "create" && action != "update" {
351				continue
352			}
353			after := snapshotOf(configByAddress[address])
354			change := planChange{Address: address, Action: action, After: &after}
355			if action == "update" {
356				before := snapshotOf(stateByAddress[address])
357				change.Before = &before
358			}
359			changes = append(changes, change)
360		}
361		return changes, summary
362	}
363	
364	// snapshotOf renders a resource as a change snapshot with its dependencies
365	// normalized to ascending order.
366	func snapshotOf(resource planResource) planSnapshot {
367		deps := make([]string, len(resource.dependsOn))
368		copy(deps, resource.dependsOn)
369		sort.Strings(deps)
370		return planSnapshot{
371			Type:       resource.typ,
372			Properties: resource.properties,
373			DependsOn:  deps,
374		}
375	}
376	
377	// resourceEqual reports whether a desired and a prior resource are
378	// equivalent: same type, deeply equal properties, and equal dependency sets.
379	func resourceEqual(desired, prior planResource) bool {
380		if desired.typ != prior.typ {
381			return false
382		}
383		if !jsonValueEqual(desired.properties, prior.properties) {
384			return false
385		}
386		return stringSetEqual(desired.dependsOn, prior.dependsOn)
387	}
388	
389	// jsonValueEqual compares two decoded JSON values. Object key order is
390	// ignored, numbers compare by numeric value, and arrays are ordered.
391	func jsonValueEqual(a, b any) bool {
392		switch av := a.(type) {
393		case json.Number:
394			bv, ok := b.(json.Number)
395			return ok && jsonNumberEqual(av, bv)
396		case map[string]any:
397			bv, ok := b.(map[string]any)
398			if !ok || len(av) != len(bv) {
399				return false
400			}
401			for key, value := range av {
402				other, present := bv[key]
403				if !present || !jsonValueEqual(value, other) {
404					return false
405				}
406			}
407			return true
408		case []any:
409			bv, ok := b.([]any)
410			if !ok || len(av) != len(bv) {
411				return false
412			}
413			for i := range av {
414				if !jsonValueEqual(av[i], bv[i]) {
415					return false
416				}
417			}
418			return true
419		default:
420			return a == b
421		}
422	}
423	
424	// jsonNumberEqual compares two JSON number literals by numeric value, so
425	// 1, 1.0, and 1e0 are all equal.
426	func jsonNumberEqual(a, b json.Number) bool {
427		ra, okA := new(big.Rat).SetString(a.String())
428		rb, okB := new(big.Rat).SetString(b.String())
429		if okA && okB {
430			return ra.Cmp(rb) == 0
431		}
432		return a.String() == b.String()
433	}
434	
435	// stringSetEqual compares two duplicate-free string lists as sets.
436	func stringSetEqual(a, b []string) bool {
437		if len(a) != len(b) {
438			return false
439		}
440		counts := make(map[string]int, len(a))
441		for _, s := range a {
442			counts[s]++
443		}
444		for _, s := range b {
445			counts[s]--
446			if counts[s] < 0 {
447				return false
448			}
449		}
450		return true
451	}
452

