1	package server
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"io"
7		"math"
8		"net/http"
9		"sort"
10		"strconv"
11		"strings"
12	)
13	
14	// Error codes reported by the configuration validator.
15	const (
16		codeInvalidJSON             = "invalid_json"
17		codeInvalidDocument         = "invalid_document"
18		codeDuplicateIdentifier     = "duplicate_identifier"
19		codeUnknownResourceType     = "unknown_resource_type"
20		codeTypeMismatch            = "type_mismatch"
21		codeMissingRequiredProperty = "missing_required_property"
22		codeUnexpectedProperty      = "unexpected_property"
23		codeUnknownDependency       = "unknown_dependency"
24		codeSelfDependency          = "self_dependency"
25		codeDuplicateDependency     = "duplicate_dependency"
26		codeDependencyCycle         = "dependency_cycle"
27	)
28	
29	// validationError is one machine-readable finding. Path is an RFC 6901 JSON
30	// Pointer into the submitted document.
31	type validationError struct {
32		Code    string `json:"code"`
33		Message string `json:"message"`
34		Path    string `json:"path"`
35	}
36	
37	type validateResponse struct {
38		Valid  bool              `json:"valid"`
39		Errors []validationError `json:"errors"`
40	}
41	
42	// handleValidateConfiguration validates a configuration document without
43	// creating or persisting anything.
44	func handleValidateConfiguration(w http.ResponseWriter, r *http.Request) {
45		w.Header().Set("Content-Type", "application/json; charset=utf-8")
46		if r.Method != http.MethodPost {
47			w.Header().Set("Allow", http.MethodPost)
48			w.WriteHeader(http.StatusMethodNotAllowed)
49			_ = json.NewEncoder(w).Encode(map[string]any{
50				"error": map[string]string{"code": "method_not_allowed"},
51			})
52			return
53		}
54	
55		doc, ok := decodeConfigurationBody(w, r)
56		if !ok {
57			return
58		}
59	
60		errs := validateConfiguration(doc)
61		sortValidationErrors(errs)
62		if len(errs) == 0 {
63			writeValidation(w, http.StatusOK, nil)
64			return
65		}
66		writeValidation(w, http.StatusUnprocessableEntity, errs)
67	}
68	
69	// decodeConfigurationBody reads the single JSON value expected from a
70	// configuration request body. It writes the shared 400 invalid_json response
71	// and returns ok=false when the body is empty, malformed, or trailing data.
72	func decodeConfigurationBody(w http.ResponseWriter, r *http.Request) (any, bool) {
73		dec := json.NewDecoder(r.Body)
74		dec.UseNumber()
75		var doc any
76		if err := dec.Decode(&doc); err != nil {
77			writeValidation(w, http.StatusBadRequest, []validationError{{
78				Code:    codeInvalidJSON,
79				Message: "request body is empty or is not valid JSON",
80				Path:    "",
81			}})
82			return nil, false
83		}
84		var trailing any
85		if err := dec.Decode(&trailing); err != io.EOF {
86			writeValidation(w, http.StatusBadRequest, []validationError{{
87				Code:    codeInvalidJSON,
88				Message: "request body must contain exactly one JSON value",
89				Path:    "",
90			}})
91			return nil, false
92		}
93		return doc, true
94	}
95	
96	// sortValidationErrors orders findings by JSON Pointer path, then by code.
97	func sortValidationErrors(errs []validationError) {
98		sort.SliceStable(errs, func(i, j int) bool {
99			if errs[i].Path != errs[j].Path {
100				return errs[i].Path < errs[j].Path
101			}
102			return errs[i].Code < errs[j].Code
103		})
104	}
105	
106	func writeValidation(w http.ResponseWriter, status int, errs []validationError) {
107		if errs == nil {
108			errs = []validationError{}
109		}
110		w.WriteHeader(status)
111		_ = json.NewEncoder(w).Encode(validateResponse{Valid: len(errs) == 0, Errors: errs})
112	}
113	
114	// pointerEscape escapes a single JSON Pointer path segment per RFC 6901.
115	func pointerEscape(s string) string {
116		s = strings.ReplaceAll(s, "~", "~0")
117		return strings.ReplaceAll(s, "/", "~1")
118	}
119	
120	// validateConfiguration checks a decoded document and returns every
121	// independently determinable problem, in discovery order.
122	func validateConfiguration(doc any) []validationError {
123		var errs []validationError
124		add := func(code, message, path string) {
125			errs = append(errs, validationError{Code: code, Message: message, Path: path})
126		}
127	
128		root, ok := doc.(map[string]any)
129		if !ok {
130			add(codeInvalidDocument, "document must be a JSON object", "")
131			return errs
132		}
133		for key := range root {
134			if key != "resourceTypes" && key != "resources" {
135				add(codeInvalidDocument, fmt.Sprintf("unknown field %q", key), "/"+pointerEscape(key))
136			}
137		}
138	
139		typesRaw, hasTypes := root["resourceTypes"]
140		if !hasTypes {
141			add(codeInvalidDocument, `missing required field "resourceTypes"`, "")
142		}
143		resourcesRaw, hasResources := root["resources"]
144		if !hasResources {
145			add(codeInvalidDocument, `missing required field "resources"`, "")
146		}
147	
148		var typeEntries []any
149		if hasTypes {
150			arr, ok := typesRaw.([]any)
151			if !ok {
152				add(codeInvalidDocument, `"resourceTypes" must be an array`, "/resourceTypes")
153			} else {
154				typeEntries = arr
155			}
156		}
157		var resourceEntries []any
158		if hasResources {
159			arr, ok := resourcesRaw.([]any)
160			if !ok {
161				add(codeInvalidDocument, `"resources" must be an array`, "/resources")
162			} else {
163				resourceEntries = arr
164			}
165		}
166	
167		// declared holds every non-empty type name seen, even when its entry is
168		// invalid or a duplicate; usable holds only names with a valid, unique
169		// schema. Resources referencing a declared-but-unusable name are spared
170		// property-level errors.
171		declared := map[string]bool{}
172		usable := map[string]any{}
173		for i, entry := range typeEntries {
174			entryPath := fmt.Sprintf("/resourceTypes/%d", i)
175			obj, ok := entry.(map[string]any)
176			if !ok {
177				add(codeInvalidDocument, "resource type entry must be an object", entryPath)
178				continue
179			}
180			name, nameValid := identifierField(obj, "name", entryPath, add)
181			schemaRaw, hasSchema := obj["schema"]
182			schemaValid := false
183			if !hasSchema {
184				add(codeInvalidDocument, `missing required field "schema"`, entryPath)
185			} else {
186				before := len(errs)
187				validateSchema(schemaRaw, entryPath+"/schema", add)
188				schemaValid = len(errs) == before
189			}
190			if !nameValid {
191				continue
192			}
193			if declared[name] {
194				add(codeDuplicateIdentifier, fmt.Sprintf("duplicate resource type name %q", name), entryPath+"/name")
195				delete(usable, name)
196				continue
197			}
198			declared[name] = true
199			if schemaValid {
200				usable[name] = schemaRaw
201			}
202		}
203	
204		seenAddresses := map[string]bool{}
205		for i, entry := range resourceEntries {
206			entryPath := fmt.Sprintf("/resources/%d", i)
207			obj, ok := entry.(map[string]any)
208			if !ok {
209				add(codeInvalidDocument, "resource entry must be an object", entryPath)
210				continue
211			}
212			if address, ok := identifierField(obj, "address", entryPath, add); ok {
213				if seenAddresses[address] {
214					add(codeDuplicateIdentifier, fmt.Sprintf("duplicate resource address %q", address), entryPath+"/address")
215				} else {
216					seenAddresses[address] = true
217				}
218			}
219	
220			var schema any
221			schemaUsable := false
222			typeRaw, hasType := obj["type"]
223			typeName, typeIsString := typeRaw.(string)
224			switch {
225			case !hasType:
226				add(codeInvalidDocument, `missing required field "type"`, entryPath)
227			case !typeIsString:
228				add(codeInvalidDocument, `"type" must be a string`, entryPath+"/type")
229			case typeName == "":
230				add(codeInvalidDocument, `"type" must not be empty`, entryPath+"/type")
231			case !declared[typeName]:
232				add(codeUnknownResourceType, fmt.Sprintf("unknown resource type %q", typeName), entryPath+"/type")
233			default:
234				if s, ok := usable[typeName]; ok {
235					schema, schemaUsable = s, true
236				}
237			}
238	
239			propsRaw, hasProps := obj["properties"]
240			if !hasProps {
241				add(codeInvalidDocument, `missing required field "properties"`, entryPath)
242				continue
243			}
244			props, ok := propsRaw.(map[string]any)
245			if !ok {
246				add(codeInvalidDocument, `"properties" must be an object`, entryPath+"/properties")
247				continue
248			}
249			if schemaUsable {
250				validateValue(props, schema, entryPath+"/properties", add)
251			}
252		}
253	
254		return errs
255	}
