442	// blockingProvider blocks inside Apply until released, so tests can observe
443	// the state lock while a run is in flight.
444	type blockingProvider struct {
445		entered chan struct{}
446		release chan struct{}
447		once    sync.Once
448	}
449	
450	func (p *blockingProvider) Apply(req ChangeRequest) error {
451		p.once.Do(func() { close(p.entered) })
452		<-p.release
453		return nil
454	}
