460		// A separately created handler for the same path shares the lock.
461		second := HandlerWithProviderAndStateFile(&recordingProvider{}, path)
462	
463		body := stateConfigBody(`[` + resEntry("a", `[]`) + `]`)
464		type outcome struct{ status int }
465		done := make(chan outcome, 1)
466		go func() {
467			res := doStateApply(t, first, body)
468			done <- outcome{res.status}
469		}()
470	
471		<-provider.entered
472		res := doStateApply(t, second, body)
473		if res.status != http.StatusConflict {
474			t.Fatalf("concurrent run: status = %d, want 409", res.status)
475		}
476		if len(res.Errors) != 1 || res.Errors[0].Code != codeStateLocked {
477			t.Fatalf("concurrent run: errors = %+v, want state_locked", res.Errors)
478		}
