480		close(provider.release)
481		if got := <-done; got.status != http.StatusOK {
482			t.Fatalf("first run: status = %d, want 200", got.status)
483		}
484	
485		// The lock was released: a later run proceeds.
486		third := doStateApply(t, second, body)
487		if third.status != http.StatusOK {
488			t.Fatalf("post-lock run: status = %d, want 200", third.status)
489		}
