508		// be committed, so the run fails at the write step.
509		path := filepath.Join(t.TempDir(), "missing", "state.json")
510		provider := &recordingProvider{}
511		handler := HandlerWithProviderAndStateFile(provider, path)
512	
513		res := doStateApply(t, handler, stateConfigBody(`[`+resEntry("a", `[]`)+`]`))
514		if res.status != http.StatusInternalServerError {
515			t.Fatalf("status = %d, want 500", res.status)
516		}
517		if len(res.Errors) != 1 || res.Errors[0].Code != codeStateWriteError {
518			t.Fatalf("errors = %+v, want state_write_error", res.Errors)
519		}
520		// The executed change and the state that could not be committed are
521		// still reported.
522		if res.Applied == nil || len(*res.Applied) != 1 || (*res.Applied)[0].Address != "a" {
523			t.Fatalf("applied = %v, want [a]", res.Applied)
524		}
525		if res.State == nil || len(res.State.Resources) != 1 || res.State.Resources[0].Address != "a" {
526			t.Fatalf("state = %+v, want pending state with a", res.State)
527		}
528		if _, err := os.Stat(path); !os.IsNotExist(err) {
529			t.Fatalf("failed commit must not leave a file behind")
530		}
531	}
532	
533	func TestStateApplyWriteFailurePreservesExistingFile(t *testing.T) {
534		if os.Geteuid() == 0 {
535			t.Skip("permission-based test does not apply to root")
536		}
537		dir := t.TempDir()
538		path := filepath.Join(dir, "state.json")
539		handler := HandlerWithProviderAndStateFile(&recordingProvider{}, path)
540	
541		// Commit one resource, then make the directory read-only so the atomic
542		// replace of the next commit fails.
543		first := doStateApply(t, handler, stateConfigBody(`[`+resEntry("a", `[]`)+`]`))
544		if first.status != http.StatusOK {
545			t.Fatalf("setup run: status = %d", first.status)
546		}
547		original := fileContent(t, path)
548		if err := os.Chmod(dir, 0o555); err != nil {
549			t.Fatal(err)
550		}
551		defer os.Chmod(dir, 0o755)
552	
553		res := doStateApply(t, handler, stateConfigBody(`[`+resEntry("a", `[]`)+`,`+resEntry("b", `[]`)+`]`))
554		if res.status != http.StatusInternalServerError {
555			t.Fatalf("status = %d, want 500", res.status)
556		}
557		if len(res.Errors) != 1 || res.Errors[0].Code != codeStateWriteError {
558			t.Fatalf("errors = %+v, want state_write_error", res.Errors)
559		}
560		if got := fileContent(t, path); got != original {
561			t.Fatalf("original file changed after failed commit:\n%s", got)
562		}
563		// No half-written temporary file is left behind.
564		entries, err := os.ReadDir(dir)
565		if err != nil {
566			t.Fatal(err)
567		}
568		if len(entries) != 1 || entries[0].Name() != "state.json" {
569			t.Fatalf("directory holds %v, want only state.json", entries)
570		}
571	}
572	
573	func TestStateApplySeparatelyCreatedHandlersShareFile(t *testing.T) {
574		path := stateFilePath(t)
575		first := HandlerWithProviderAndStateFile(&recordingProvider{}, path)
576		second := HandlerWithProviderAndStateFile(&recordingProvider{}, path)
577	
578		if res := doStateApply(t, first, stateConfigBody(`[`+resEntry("a", `[]`)+`]`)); res.status != http.StatusOK {
579			t.Fatalf("first handler: status = %d", res.status)
580		}
581		// The second handler observes the committed revision.
582		res := doStateApply(t, second, stateConfigBody(`[`+resEntry("a", `[]`)+`,`+resEntry("b", `[]`)+`]`))
583		if res.status != http.StatusOK || res.Revision == nil || *res.Revision != 2 {
584			t.Fatalf("second handler: status = %d revision = %v, want 200/2", res.status, res.Revision)
585		}
586		if res.Applied == nil || len(*res.Applied) != 1 || (*res.Applied)[0].Address != "b" {
587			t.Fatalf("second handler applied = %v, want only create b", res.Applied)
588		}
589	}
590	
591	func TestStateApplyKeepsOtherEndpointsWorking(t *testing.T) {
592		handler := HandlerWithProviderAndStateFile(&recordingProvider{}, stateFilePath(t))
593	
594		health := httptest.NewRecorder()
595		handler.ServeHTTP(health, httptest.NewRequest(http.MethodGet, "/healthz", nil))
596		if health.Code != http.StatusOK {
597			t.Fatalf("healthz status = %d", health.Code)
598		}
599	
600		rec := httptest.NewRecorder()
601		handler.ServeHTTP(rec, httptest.NewRequest(http.MethodPost, "/v1/plans",
602			strings.NewReader(planBody(`[`+resEntry("a", `[]`)+`]`, `[]`))))
603		if rec.Code != http.StatusOK {
604			t.Fatalf("plans status = %d", rec.Code)
605		}
606	
607		applyRec := httptest.NewRecorder()
608		handler.ServeHTTP(applyRec, httptest.NewRequest(http.MethodPost, "/v1/apply",
609			strings.NewReader(planBody(`[`+resEntry("a", `[]`)+`]`, `[]`))))
610		if applyRec.Code != http.StatusOK {
611			t.Fatalf("apply status = %d", applyRec.Code)
612		}
613	}
